package ee.schimke.ha.rc.components

import androidx.compose.ui.graphics.ImageBitmap
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * Images a card bakes in from the app rather than fetching: Greg Bullock's G-SPOT wordmark from his
 * GShark watch face, made for the Rugged Digital card style with him. White letters over their
 * black outline, set on the face's arc, as the watch draws them.
 */
object HaBundledImages {
  /** The G-SPOT wordmark's PNG bytes, 460 × 110, from the face's 4× master. */
  @OptIn(ExperimentalEncodingApi::class)
  val gSpotWordmark: ByteArray by lazy { Base64.decode(GSpotWordmarkBase64) }

  /** The wordmark decoded, or null where the host has no image decoder (a plain-JVM bake). */
  val gSpotWordmarkBitmap: ImageBitmap? by lazy { decodeBundledImage(gSpotWordmark) }
}

/** [bytes] (a PNG) decoded for this platform, or null when it can't decode one. */
internal expect fun decodeBundledImage(bytes: ByteArray): ImageBitmap?

